package main

import (
	"slices"
	"strings"
)

type clipKind int

const (
	clipSkip clipKind = iota
	clipText
	clipImage
)

// privateClipTypes are the nspasteboard.org markers password managers and
// similar sources set to ask clipboard history tools not to record a copy.
var privateClipTypes = []string{
	"org.nspasteboard.ConcealedType",
	"org.nspasteboard.TransientType",
	"org.nspasteboard.AutoGeneratedType",
	"com.agilebits.onepassword",
	"de.petermaurer.TransientPasteboardType",
	"net.antelle.keeweb",
}

var (
	clipTextTypes  = []string{"public.utf8-plain-text", "public.utf16-plain-text", "NSStringPboardType"}
	clipImageTypes = []string{"public.png", "public.tiff", "NSTIFFPboardType"}
)

// classifyClipboard decides what a clipboard change should add, from the
// pasteboard's declared types in the source's order of preference.
// Finder file copies are skipped: their image is only the file icon and
// their text only the file name. When both text and an image are offered
// (Office, Numbers, web pages), the representation the source lists
// first wins, so a spreadsheet copy is kept as text and a copied picture
// as an image.
func classifyClipboard(types []string) clipKind {
	for _, t := range types {
		if slices.Contains(privateClipTypes, t) {
			return clipSkip
		}
	}
	if slices.Contains(types, "public.file-url") || slices.Contains(types, "NSFilenamesPboardType") {
		return clipSkip
	}
	for _, t := range types {
		switch {
		case slices.Contains(clipTextTypes, t):
			return clipText
		case slices.Contains(clipImageTypes, t):
			return clipImage
		}
	}
	return clipSkip
}

// clipboardExcluded reports whether a copy is from an app the user chose
// not to record: bundleID is compared to the excludedApps setting without
// case, as Launch Services compares bundle identifiers. An unknown source
// ("" — the system reported no frontmost app) is never excluded.
func clipboardExcluded(bundleID string, excluded []string) bool {
	if bundleID == "" {
		return false
	}
	for _, id := range excluded {
		if strings.EqualFold(strings.TrimSpace(id), bundleID) {
			return true
		}
	}
	return false
}

// clipCapture decides what one clipboard change records: nothing from an
// app the user excluded, otherwise whatever the change's declared types
// say (see classifyClipboard).
func clipCapture(types []string, sourceApp string, excluded []string) clipKind {
	if clipboardExcluded(sourceApp, excluded) {
		return clipSkip
	}
	return classifyClipboard(types)
}

// captureSource is the provenance stamped on a capture: the bundle id of
// the app that was frontmost when the pasteboard changed, or "" when the
// source is unknown — including when ShelfU itself is frontmost, which
// only happens while the keyboard search is open and must not record
// itself. Pure; unit-tested.
func captureSource(frontPID, ownPID int, bundleID string) string {
	if frontPID == ownPID {
		return ""
	}
	return bundleID
}
